<?php

namespace App\Core\AI\Services;

use App\Models\AdmissionLead;
use App\Models\CrmTask;
use App\Models\LeadFollowUp;
use App\Models\ParentComplaint;
use App\Models\School;
use App\Models\StudentEngagementRecord;
use App\Models\User;
use Carbon\Carbon;
use Illuminate\Support\Str;

class ManagementQueryEngine
{
    /**
     * Convert natural language prompt into safe, read-only metrics queries using a controlled query layer.
     * ZERO arbitrary SQL generated by LLM is executed directly.
     */
    public function executeQuery(string $prompt, User $user): array
    {
        $schoolId = $user->school_id ?? School::first()->id ?? 1;
        $lowerPrompt = mb_strtolower($prompt);

        // Classify Intent & Dispatch to Predefined Controlled Query Tool
        if (str_contains($lowerPrompt, 'pending follow') || str_contains($lowerPrompt, 'leads pending')) {
            return $this->queryPendingAdmissionFollowups($schoolId);
        }

        if (str_contains($lowerPrompt, 'attendance below') || str_contains($lowerPrompt, 'low attendance') || str_contains($lowerPrompt, 'attendance threshold')) {
            return $this->queryAttendanceBelowThreshold($schoolId);
        }

        if (str_contains($lowerPrompt, 'unresolved complaint') || str_contains($lowerPrompt, 'today\'s complaint') || str_contains($lowerPrompt, 'open complaint')) {
            return $this->queryUnresolvedComplaints($schoolId);
        }

        if (str_contains($lowerPrompt, 'admission performance') || str_contains($lowerPrompt, 'monthly admission') || str_contains($lowerPrompt, 'summarize admission')) {
            return $this->queryAdmissionPerformanceSummary($schoolId);
        }

        if (str_contains($lowerPrompt, 'overdue') || str_contains($lowerPrompt, 'past due')) {
            return $this->queryOverdueFollowups($schoolId);
        }

        // Fallback: General Executive Management Overview
        return $this->queryGeneralExecutiveOverview($schoolId, $prompt);
    }

    /**
     * Controlled Tool 1: Pending Admission Follow-ups
     */
    protected function queryPendingAdmissionFollowups(int $schoolId): array
    {
        $pendingFollowups = LeadFollowUp::with('lead')
            ->whereHas('lead', function ($q) use ($schoolId) {
                $q->where('school_id', $schoolId);
            })
            ->where('status', 'pending')
            ->orderBy('due_date', 'asc')
            ->take(10)
            ->get();

        $totalPendingCount = LeadFollowUp::whereHas('lead', function ($q) use ($schoolId) {
            $q->where('school_id', $schoolId);
        })->where('status', 'pending')->count();

        $overdueCount = LeadFollowUp::whereHas('lead', function ($q) use ($schoolId) {
            $q->where('school_id', $schoolId);
        })->where('status', 'pending')->where('due_date', '<', now())->count();

        $records = $pendingFollowups->map(function ($f) {
            return [
                'id' => $f->id,
                'title' => $f->subject ?: "Follow-up for {$f->lead?->parent_name}",
                'subtitle' => "Lead: {$f->lead?->student_name} (Parent: {$f->lead?->parent_name}) - Stage: " . strtoupper($f->lead?->stage ?? 'Inquiry'),
                'status' => $f->due_date && Carbon::parse($f->due_date)->isPast() ? 'Overdue' : 'Pending',
                'status_color' => $f->due_date && Carbon::parse($f->due_date)->isPast() ? 'rose' : 'amber',
                'date' => $f->due_date ? Carbon::parse($f->due_date)->format('M d, Y') : 'No due date',
                'drill_down_url' => route('admissions.show', $f->lead_id ?? 1),
            ];
        })->toArray();

        return [
            'answer' => "There are currently **{$totalPendingCount} pending admission follow-ups** requiring staff attention across the pipeline, of which **{$overdueCount} are past SLA deadline**.",
            'supporting_metrics' => [
                ['label' => 'Total Pending Follow-ups', 'value' => $totalPendingCount, 'color' => 'amber'],
                ['label' => 'Overdue Past SLA', 'value' => $overdueCount, 'color' => 'rose'],
                ['label' => 'Total Active Leads', 'value' => AdmissionLead::where('school_id', $schoolId)->count(), 'color' => 'indigo'],
            ],
            'relevant_records' => $records,
            'date_range' => 'Current Academic Term (September 2026)',
            'filters_used' => [
                'school_id' => $schoolId,
                'lead_followup_status' => 'pending',
                'query_type' => 'controlled_eloquent_query',
            ],
        ];
    }

    /**
     * Controlled Tool 2: Attendance Below Configured Threshold (Default: 85%)
     */
    protected function queryAttendanceBelowThreshold(int $schoolId, float $threshold = 85.0): array
    {
        $lowAttendanceRecords = StudentEngagementRecord::with('student.schoolClass')
            ->where('school_id', $schoolId)
            ->where('attendance_percentage', '<', $threshold)
            ->orderBy('attendance_percentage', 'asc')
            ->take(10)
            ->get();

        $countBelowThreshold = StudentEngagementRecord::where('school_id', $schoolId)
            ->where('attendance_percentage', '<', $threshold)
            ->count();

        $avgAttendanceOverall = round(StudentEngagementRecord::where('school_id', $schoolId)->avg('attendance_percentage') ?? 90, 1);

        $records = $lowAttendanceRecords->map(function ($r) {
            return [
                'id' => $r->id,
                'title' => $r->student?->full_name ?? 'Student',
                'subtitle' => "Class: " . ($r->student?->schoolClass?->name ?? 'Unassigned') . " | Present: {$r->attendance_days_present} days, Absent: {$r->attendance_days_absent} days",
                'status' => "{$r->attendance_percentage}% Attendance",
                'status_color' => 'amber',
                'date' => "Evaluated " . ($r->last_evaluated_at ? $r->last_evaluated_at->diffForHumans() : 'Recently'),
                'drill_down_url' => route('students.show', $r->student_id),
            ];
        })->toArray();

        return [
            'answer' => "A total of **{$countBelowThreshold} students** currently have attendance levels below the configured threshold of **{$threshold}%**. Overall school average attendance stands at **{$avgAttendanceOverall}%**.",
            'supporting_metrics' => [
                ['label' => 'Students Below Threshold', 'value' => $countBelowThreshold, 'color' => 'amber'],
                ['label' => 'Configured Threshold', 'value' => "{$threshold}%", 'color' => 'slate'],
                ['label' => 'School-wide Attendance Avg', 'value' => "{$avgAttendanceOverall}%", 'color' => 'emerald'],
            ],
            'relevant_records' => $records,
            'date_range' => 'Current Academic Year (2026-2027)',
            'filters_used' => [
                'school_id' => $schoolId,
                'attendance_threshold' => "< {$threshold}%",
                'query_type' => 'controlled_eloquent_query',
            ],
        ];
    }

    /**
     * Controlled Tool 3: Today's / Unresolved Complaints
     */
    protected function queryUnresolvedComplaints(int $schoolId): array
    {
        $unresolved = ParentComplaint::with('parent', 'student')
            ->where('school_id', $schoolId)
            ->whereIn('status', ['open', 'in_progress'])
            ->orderBy('created_at', 'desc')
            ->take(10)
            ->get();

        $totalUnresolvedCount = ParentComplaint::where('school_id', $schoolId)
            ->whereIn('status', ['open', 'in_progress'])
            ->count();

        $todayComplaintsCount = ParentComplaint::where('school_id', $schoolId)
            ->whereDate('created_at', Carbon::today())
            ->count();

        $highPriorityCount = ParentComplaint::where('school_id', $schoolId)
            ->whereIn('status', ['open', 'in_progress'])
            ->where('priority', 'high')
            ->count();

        $records = $unresolved->map(function ($c) {
            return [
                'id' => $c->id,
                'title' => "Ticket #{$c->ticket_number}: {$c->subject}",
                'subtitle' => "Parent: " . ($c->parent?->full_name ?? 'Parent') . " (Child: " . ($c->student?->full_name ?? 'Student') . ") - Category: " . ucfirst($c->category),
                'status' => strtoupper($c->status),
                'status_color' => $c->priority === 'high' ? 'rose' : 'amber',
                'date' => $c->created_at->format('M d, Y h:i A'),
                'drill_down_url' => route('parents.communication-log'),
            ];
        })->toArray();

        return [
            'answer' => "There are **{$totalUnresolvedCount} unresolved parent complaint tickets** currently open, including **{$todayComplaintsCount} logged today** and **{$highPriorityCount} marked high priority**.",
            'supporting_metrics' => [
                ['label' => 'Total Unresolved Tickets', 'value' => $totalUnresolvedCount, 'color' => 'amber'],
                ['label' => 'Logged Today', 'value' => $todayComplaintsCount, 'color' => 'indigo'],
                ['label' => 'High Priority Open', 'value' => $highPriorityCount, 'color' => 'rose'],
            ],
            'relevant_records' => $records,
            'date_range' => 'Real-Time Live (Today, ' . Carbon::today()->format('M d, Y') . ')',
            'filters_used' => [
                'school_id' => $schoolId,
                'complaint_status' => 'open, in_progress',
                'query_type' => 'controlled_eloquent_query',
            ],
        ];
    }

    /**
     * Controlled Tool 4: Admission Performance Summary
     */
    protected function queryAdmissionPerformanceSummary(int $schoolId): array
    {
        $totalLeads = AdmissionLead::where('school_id', $schoolId)->count();
        $enrolledCount = AdmissionLead::where('school_id', $schoolId)->where('stage', 'enrolled')->count();
        $newThisMonth = AdmissionLead::where('school_id', $schoolId)->whereDate('created_at', '>=', Carbon::now()->startOfMonth())->count();

        $conversionRate = $totalLeads > 0 ? round(($enrolledCount / $totalLeads) * 100, 1) : 0;

        $recentLeads = AdmissionLead::where('school_id', $schoolId)
            ->orderBy('created_at', 'desc')
            ->take(10)
            ->get();

        $records = $recentLeads->map(function ($l) {
            return [
                'id' => $l->id,
                'title' => "Lead: {$l->student_name}",
                'subtitle' => "Parent: {$l->parent_name} | Phone: {$l->phone} | Email: {$l->email}",
                'status' => strtoupper(str_replace('_', ' ', $l->stage)),
                'status_color' => $l->stage === 'enrolled' ? 'emerald' : 'indigo',
                'date' => $l->created_at->format('M d, Y'),
                'drill_down_url' => route('admissions.show', $l->id),
            ];
        })->toArray();

        return [
            'answer' => "Admission CRM performance summary for **" . Carbon::now()->format('F Y') . "**: Total **{$totalLeads} admission leads** logged in pipeline, **{$newThisMonth} new leads added this month**, with an overall conversion rate of **{$conversionRate}%** ({$enrolledCount} enrolled).",
            'supporting_metrics' => [
                ['label' => 'Total Pipeline Leads', 'value' => $totalLeads, 'color' => 'indigo'],
                ['label' => 'New Leads This Month', 'value' => $newThisMonth, 'color' => 'purple'],
                ['label' => 'Lead Conversion Rate', 'value' => "{$conversionRate}%", 'color' => 'emerald'],
            ],
            'relevant_records' => $records,
            'date_range' => Carbon::now()->startOfMonth()->format('M 01, Y') . ' to ' . Carbon::now()->format('M d, Y'),
            'filters_used' => [
                'school_id' => $schoolId,
                'timeframe' => 'current_month',
                'query_type' => 'controlled_eloquent_query',
            ],
        ];
    }

    /**
     * Controlled Tool 5: Overdue Follow-ups & Tasks
     */
    protected function queryOverdueFollowups(int $schoolId): array
    {
        $overdueTasks = CrmTask::where('school_id', $schoolId)
            ->where('status', 'overdue')
            ->orWhere(function ($q) use ($schoolId) {
                $q->where('school_id', $schoolId)
                    ->where('status', 'pending')
                    ->where('due_date', '<', now());
            })
            ->orderBy('due_date', 'asc')
            ->take(10)
            ->get();

        $totalOverdueCount = CrmTask::where('school_id', $schoolId)
            ->where(function ($q) {
                $q->where('status', 'overdue')
                    ->orWhere(function ($q2) {
                        $q2->where('status', 'pending')->where('due_date', '<', now());
                    });
            })
            ->count();

        $records = $overdueTasks->map(function ($t) {
            return [
                'id' => $t->id,
                'title' => $t->title,
                'subtitle' => "Category: " . ucfirst($t->category ?? 'general') . " | Priority: " . ucfirst($t->priority),
                'status' => 'OVERDUE',
                'status_color' => 'rose',
                'date' => $t->due_date ? Carbon::parse($t->due_date)->format('M d, Y') : 'Past due',
                'drill_down_url' => route('tasks.show', $t->id),
            ];
        })->toArray();

        return [
            'answer' => "There are currently **{$totalOverdueCount} overdue follow-up tasks** requiring urgent staff resolution across departments.",
            'supporting_metrics' => [
                ['label' => 'Total Overdue Tasks', 'value' => $totalOverdueCount, 'color' => 'rose'],
                ['label' => 'High Priority Overdue', 'value' => CrmTask::where('school_id', $schoolId)->where('status', 'overdue')->where('priority', 'high')->count(), 'color' => 'amber'],
                ['label' => 'Resolved This Week', 'value' => CrmTask::where('school_id', $schoolId)->where('status', 'completed')->whereDate('updated_at', '>=', Carbon::now()->startOfWeek())->count(), 'color' => 'emerald'],
            ],
            'relevant_records' => $records,
            'date_range' => 'Past Due (Prior to ' . Carbon::now()->format('M d, Y') . ')',
            'filters_used' => [
                'school_id' => $schoolId,
                'task_status' => 'overdue',
                'query_type' => 'controlled_eloquent_query',
            ],
        ];
    }

    /**
     * Controlled Tool Fallback: General Executive Management Overview
     */
    protected function queryGeneralExecutiveOverview(int $schoolId, string $prompt): array
    {
        $totalLeads = AdmissionLead::where('school_id', $schoolId)->count();
        $openComplaints = ParentComplaint::where('school_id', $schoolId)->whereIn('status', ['open', 'in_progress'])->count();
        $overdueTasks = CrmTask::where('school_id', $schoolId)->where('status', 'overdue')->count();

        $sampleLeads = AdmissionLead::where('school_id', $schoolId)->latest()->take(5)->get();

        $records = $sampleLeads->map(function ($l) {
            return [
                'id' => $l->id,
                'title' => "Lead: {$l->student_name} (Parent: {$l->parent_name})",
                'subtitle' => "Stage: " . strtoupper(str_replace('_', ' ', $l->stage)) . " | Phone: {$l->phone}",
                'status' => 'ACTIVE LEAD',
                'status_color' => 'indigo',
                'date' => $l->created_at->format('M d, Y'),
                'drill_down_url' => route('admissions.show', $l->id),
            ];
        })->toArray();

        return [
            'answer' => "Executive summary based on your query *\"{$prompt}\"*: Operating across **{$totalLeads} active admission leads**, **{$openComplaints} open parent complaints**, and **{$overdueTasks} overdue task items**.",
            'supporting_metrics' => [
                ['label' => 'Total Admission Leads', 'value' => $totalLeads, 'color' => 'indigo'],
                ['label' => 'Open Parent Complaints', 'value' => $openComplaints, 'color' => 'amber'],
                ['label' => 'Overdue Tasks', 'value' => $overdueTasks, 'color' => 'rose'],
            ],
            'relevant_records' => $records,
            'date_range' => 'Current Academic Term (2026-2027)',
            'filters_used' => [
                'school_id' => $schoolId,
                'query_type' => 'controlled_eloquent_query',
            ],
        ];
    }
}
